begin; select plan(26);
select has_table('public','tracekit_production_controls','production controls exist');
select has_table('public','commerce_connection_pauses','Connection pause exists');
select has_table('public','tkid_handoff_keys','handoff key references exist');
select has_table('public','tracekit_operational_alerts','internal alert contract exists');
select has_column('public','commerce_sync_schedules','activation_state','schedule activation state explicit');
select has_column('public','tkid_sources','sdk_version','SDK version pin persisted');
select has_function('public','commerce_schedule_permitted',array['uuid','uuid'],'scheduler permission RPC exists');
insert into public.tracekit_accounts(id,account_type,name) values('c5200000-0000-0000-0000-000000000001','client','Readiness Account');
insert into public.tracekit_organizations(id,owning_account_id,name) values('c5200000-0000-0000-0000-000000000002','c5200000-0000-0000-0000-000000000001','Readiness Org');
insert into public.tracekit_business_contexts(id,account_id,organization_id,name) values('readiness-context','c5200000-0000-0000-0000-000000000001','c5200000-0000-0000-0000-000000000002','Readiness Context');
insert into public.commerce_provider_connections(id,account_id,organization_id,provider,display_name,status) values('c5200000-0000-4000-8000-000000000003','c5200000-0000-0000-0000-000000000001','c5200000-0000-0000-0000-000000000002','commas','Readiness','connected');
insert into public.commerce_provider_accounts(id,connection_id,organization_id,provider_account_external_id) values('c5200000-0000-4000-8000-000000000004','c5200000-0000-4000-8000-000000000003','c5200000-0000-0000-0000-000000000002','readiness-provider');
insert into public.commerce_sync_schedules(account_id,organization_id,connection_id,provider_account_id,resource) values('c5200000-0000-0000-0000-000000000001','c5200000-0000-0000-0000-000000000002','c5200000-0000-4000-8000-000000000003','c5200000-0000-4000-8000-000000000004','transactions');
select is((select activation_state from public.commerce_sync_schedules where connection_id='c5200000-0000-4000-8000-000000000003'),'disabled','schedule defaults disabled');
select is((select enabled from public.commerce_sync_schedules where connection_id='c5200000-0000-4000-8000-000000000003'),false,'legacy scheduler switch remains disabled');
select is(public.commerce_schedule_permitted('c5200000-0000-0000-0000-000000000002','c5200000-0000-4000-8000-000000000003'),false,'missing global enable fails closed');
insert into public.tracekit_production_controls(account_id,organization_id,capability,activation_state) values('c5200000-0000-0000-0000-000000000001','c5200000-0000-0000-0000-000000000002','commerce_scheduler','enabled');
select is(public.commerce_schedule_permitted('c5200000-0000-0000-0000-000000000002','c5200000-0000-4000-8000-000000000003'),true,'explicit global enable permits unpaused Connection');
insert into public.commerce_connection_pauses(connection_id,organization_id,account_id,paused,reason_code,paused_at) values('c5200000-0000-4000-8000-000000000003','c5200000-0000-0000-0000-000000000002','c5200000-0000-0000-0000-000000000001',true,'operator_pause',now());
select is(public.commerce_schedule_permitted('c5200000-0000-0000-0000-000000000002','c5200000-0000-4000-8000-000000000003'),false,'Connection pause overrides global enable');
update public.commerce_connection_pauses set paused=false,resumed_at=now() where connection_id='c5200000-0000-4000-8000-000000000003';
select is(public.commerce_schedule_permitted('c5200000-0000-0000-0000-000000000002','c5200000-0000-4000-8000-000000000003'),true,'resume is non-destructive');
insert into public.tkid_sources(id,account_id,organization_id,business_context_id,public_source_id,environment,allowed_origins) values('c5200000-0000-4000-8000-000000000005','c5200000-0000-0000-0000-000000000001','c5200000-0000-0000-0000-000000000002','readiness-context','tksrc_readiness1234567','production',array['https://shop.example']);
select is((select status from public.tkid_sources where id='c5200000-0000-4000-8000-000000000005'),'disabled','production TKID source defaults disabled');
select throws_ok($sql$update public.tkid_sources set sdk_version='latest' where id='c5200000-0000-4000-8000-000000000005'$sql$,'23514',null,'SDK version must be pinned');
select throws_ok($sql$update public.tkid_sources set proof_max_journeys=101 where id='c5200000-0000-4000-8000-000000000005'$sql$,'23514',null,'proof Journey cap remains bounded');
insert into public.tkid_handoff_keys(id,organization_id,source_id,secret_reference,state,not_before,not_after) values('tkhk_current12345','c5200000-0000-0000-0000-000000000002','c5200000-0000-4000-8000-000000000005','secret://tkid/handoff/current','current',now(),now()+interval '30 days');
select is((select secret_reference from public.tkid_handoff_keys where source_id='c5200000-0000-4000-8000-000000000005'),'secret://tkid/handoff/current','only secret reference persists');
select throws_ok($sql$insert into public.tkid_handoff_keys(id,organization_id,source_id,secret_reference,state,not_before,not_after) values('tkhk_secondcurrent','c5200000-0000-0000-0000-000000000002','c5200000-0000-4000-8000-000000000005','secret://tkid/handoff/second','current',now(),now()+interval '30 days')$sql$,'23505',null,'one current handoff key per source');
select ok((select relrowsecurity from pg_class where oid='public.tracekit_production_controls'::regclass),'control RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.tkid_handoff_keys'::regclass),'handoff key RLS enabled');
select is((select count(*)::integer from information_schema.role_table_grants where table_schema='public' and table_name in('tracekit_production_controls','commerce_connection_pauses','tkid_handoff_keys','tracekit_operational_alerts') and grantee in('anon','authenticated')),0,'browser roles receive no grants');
select is((select count(*)::integer from public.commerce_repository_activation),0,'readiness migration activates no repository');
select is((select count(*)::integer from public.tkid_sources where status='shadow'),0,'readiness migration activates no TKID source');
select is((select count(*)::integer from public.commerce_sync_schedules where enabled),0,'readiness migration enables no schedules');
select lives_ok($sql$insert into public.tracekit_operational_alerts(organization_id,capability,alert_code,severity,first_observed_at,last_observed_at,safe_context) values('c5200000-0000-0000-0000-000000000002','commerce','freshness_stale','warning',now(),now(),'{"lag_minutes":61}')$sql$,'safe internal alert persists');
select throws_ok($sql$insert into public.tracekit_operational_alerts(organization_id,capability,alert_code,severity,first_observed_at,last_observed_at,safe_context) values('c5200000-0000-0000-0000-000000000002','tkid','bad','warning',now(),now(),'{"email":"unsafe@example.test"}')$sql$,'23514',null,'unsafe alert metadata fails closed');
select * from finish(); rollback;
